{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Ketoconazole, the closest structural analogue, has a measured human oral bioavailability of 76%, directly supporting F ≥ 20% for this azole antifungal scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Posaconazole, a close analogue, showed 87% oral bioavailability in Chinese subjects in the fed state, matching the query's fed-state condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Posaconazole delayed-release tablet achieved 50% absolute oral bioavailability in healthy volunteers, confirming that this chemotype can exceed 20% F when adequately formulated.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Voriconazole, another triazole antifungal, has approximately 90% human oral bioavailability, supporting the generally high absorption of this drug class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Genaconazole, a triazole antifungal, showed essentially complete (100%) absolute oral bioavailability in healthy volunteers, further supporting high F for the azole class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Posaconazole oral suspension had an absolute bioavailability of only 16% (8–27%) in immunocompromised patients, showing that formulation can lower F below 20%; this is less transferable to the query under fed conditions with a solid formulation.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic azole antifungal closely related to ketoconazole and posaconazole. The closest analogue, ketoconazole, has high human oral bioavailability (~76%), and posaconazole in the fed state reaches 87% with a tablet. The fed condition favors absorption of such lipophilic azoles. Low-availability evidence comes mainly from posaconazole suspension and is formulation-dependent, so F ≥ 20% is the better-supported prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "The pharmaceutical formulation (e.g., tablet vs suspension) is not specified for the query.",
    "The specific food effect for this exact analogue is not directly measured, though fed-state data for posaconazole support improved absorption.",
    "Solubility and dissolution behavior of the query are not directly available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

